import sys

def solve():
    lines = sys.stdin.read().splitlines()
    if not lines: return
    t = int(lines[0])
    for i in range(1, t + 1):
        parts = lines[i].split()
        if not parts: continue
        n, k = int(parts[0]), int(parts[1])
        if k % 3 != 0:
            print('Alice' if n % 3 != 0 else 'Bob')
        else:
            rem = n % (k + 1)
            if rem % 3 == 0 and rem != k:
                print('Bob')
            else:
                print('Alice')

if __name__ == '__main__':
    solve()

