def solve():
    lines = sys.stdin.read().splitlines()
    if not lines: return
    t = int(lines[0])
    for i in range(1, t + 1):
        n = int(lines[i].strip())
        if n % 2 != 0:
            print('Bob')
        else:
            cnt = 0
            temp = n
            while temp % 2 == 0:
                temp //= 2
                cnt += 1
            if temp > 1:
                print('Alice')
            else:
                print('Alice' if cnt % 2 == 0 else 'Bob')

if __name__ == '__main__':
    solve()

