import sys
import math

def solve():
    data = sys.stdin.read().split()
    if not data: return
    n = int(data[0])
    max_val = 1000000
    is_prime = bytearray([1]) * (max_val + 1)
    is_prime[0] = is_prime[1] = 0
    for p in range(2, int(max_val**0.5) + 1):
        if is_prime[p]:
            is_prime[p*p : max_val + 1 : p] = bytearray(len(is_prime[p*p : max_val + 1 : p]))
    out = []
    for i in range(1, n + 1):
        x = int(data[i])
        r = int(math.isqrt(x))
        if r * r == x and is_prime[r]:
            out.append('YES')
        else:
            out.append('NO')
    print('\n'.join(out))

if __name__ == '__main__':
    solve()
